local RunService=game:GetService("RunService")
local cloneref=(cloneref or clonereference or function(i)return i end)
local ReplicatedStorage=cloneref(game:GetService("ReplicatedStorage"))
local HttpService=cloneref(game:GetService("HttpService"))
local WindUI
do local ok,result=pcall(function()return require("./src/Init")end)
if ok then WindUI=result else if cloneref(game:GetService("RunService")):IsStudio()then WindUI=require(cloneref(ReplicatedStorage:WaitForChild("WindUI"):WaitForChild("Init")))else WindUI=loadstring(game:HttpGet("https://raw.githubusercontent.com/Footagesus/WindUI/main/dist/main.lua"))()end end end
local Players=game:GetService("Players")local LocalPlayer=Players.LocalPlayer local Camera=workspace.CurrentCamera local UIS=game:GetService("UserInputService")
local TargetWalkSpeed=16 local SpeedEnabled=false local OriginalWalkSpeed=16 local CustomJumpEnabled=false local CustomJumpValue=50 local OriginalJump=50 local InfiniteJumpEnabled=false local Flying=false local FlySpeed=50 local FlyGui=nil local FlyBodyGyro=nil local FlyBodyVelocity=nil local flyUp,flyDown,flyLeft,flyRight=false,false,false,false
local ESP_Players=false local ESP_NPCs=false local ESP_ShowName=false local ESP_ShowDistance=false local ESP_ShowHealth=false local ESP_Highlights={}local ESP_Billboards={}
function SetSpeedEnabled(e)SpeedEnabled=e local h=LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")if h then h.WalkSpeed=e and TargetWalkSpeed or OriginalWalkSpeed end end
function SetSpeedValue(v)TargetWalkSpeed=math.clamp(v,0,400)if SpeedEnabled then local h=LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")if h then h.WalkSpeed=TargetWalkSpeed end end end
LocalPlayer.CharacterAdded:Connect(function(c)task.wait(0.5)if SpeedEnabled then local h=c:FindFirstChildOfClass("Humanoid")if h then h.WalkSpeed=TargetWalkSpeed end end if CustomJumpEnabled then local h=c:FindFirstChildOfClass("Humanoid")if h then h.UseJumpPower=true h.JumpPower=CustomJumpValue h.JumpHeight=CustomJumpValue*(7.2/50)end end end)
function SetJumpEnabled(e)CustomJumpEnabled=e local h=LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")if h then if e then h.UseJumpPower=true h.JumpPower=CustomJumpValue h.JumpHeight=CustomJumpValue*(7.2/50)else h.JumpPower=OriginalJump h.JumpHeight=OriginalJump*(7.2/50)end end end
function SetJumpValue(v)CustomJumpValue=math.clamp(v,50,600)if CustomJumpEnabled then local h=LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")if h then h.UseJumpPower=true h.JumpPower=CustomJumpValue h.JumpHeight=CustomJumpValue*(7.2/50)end end end
RunService.RenderStepped:Connect(function()if CustomJumpEnabled then local c=LocalPlayer.Character if c then local h=c:FindFirstChildOfClass("Humanoid")if h then h.UseJumpPower=true h.JumpPower=CustomJumpValue h.JumpHeight=CustomJumpValue*(7.2/50)end end end if InfiniteJumpEnabled then local c=LocalPlayer.Character if c then local h=c:FindFirstChildOfClass("Humanoid")if h and h:GetState()==Enum.HumanoidStateType.Freefall then if UIS:IsKeyDown(Enum.KeyCode.Space)then h.Jump=true end end end end end)
function CreateFlyGui()if FlyGui then return FlyGui end local gui=Instance.new("ScreenGui")gui.Name="FlyControl"gui.Parent=game.CoreGui gui.IgnoreGuiInset=true gui.ResetOnSpawn=false local frame=Instance.new("Frame")frame.Size=UDim2.new(0,180,0,200)frame.Position=UDim2.new(0.5,-90,0.3,0)frame.BackgroundColor3=Color3.fromRGB(30,30,30)frame.BorderSizePixel=0 frame.Active=true frame.Draggable=true Instance.new("UICorner",frame).CornerRadius=UDim.new(0,8)frame.Parent=gui local title=Instance.new("TextLabel")title.Size=UDim2.new(1,0,0,30)title.Position=UDim2.new(0,0,0,0)title.BackgroundTransparency=1 title.Text="飞行控制"title.TextColor3=Color3.new(1,1,1)title.Font=Enum.Font.SourceSansBold title.TextSize=16 title.Parent=frame local btnSize=50 local gap=5 local startX=(180-3*btnSize-2*gap)/2 local function makeBtn(x,y,text)local b=Instance.new("TextButton")b.Size=UDim2.new(0,btnSize,0,btnSize)b.Position=UDim2.new(0,x,0,y)b.Text=text b.BackgroundColor3=Color3.fromRGB(70,70,70)b.TextColor3=Color3.new(1,1,1)b.Font=Enum.Font.SourceSansBold b.TextSize=20 b.Parent=frame return b end local upBtn=makeBtn(startX+btnSize+gap,40,"↑")local downBtn=makeBtn(startX+btnSize+gap,40+btnSize+gap,"↓")local leftBtn=makeBtn(startX,40+btnSize+gap,"←")local rightBtn=makeBtn(startX+2*(btnSize+gap),40+btnSize+gap,"→")local speedLabel=Instance.new("TextLabel")speedLabel.Size=UDim2.new(1,-20,0,20)speedLabel.Position=UDim2.new(0,10,0,40+2*(btnSize+gap)+10)speedLabel.BackgroundTransparency=1 speedLabel.Text="速度: 50"speedLabel.TextColor3=Color3.new(1,1,1)speedLabel.Font=Enum.Font.SourceSans speedLabel.TextSize=14 speedLabel.Parent=frame local decBtn=Instance.new("TextButton")decBtn.Size=UDim2.new(0,40,0,30)decBtn.Position=UDim2.new(0,20,0,40+2*(btnSize+gap)+35)decBtn.Text="-"decBtn.BackgroundColor3=Color3.fromRGB(70,70,70)decBtn.TextColor3=Color3.new(1,1,1)decBtn.Font=Enum.Font.SourceSansBold decBtn.TextSize=18 decBtn.Parent=frame local incBtn=Instance.new("TextButton")incBtn.Size=UDim2.new(0,40,0,30)incBtn.Position=UDim2.new(0,120,0,40+2*(btnSize+gap)+35)incBtn.Text="+"incBtn.BackgroundColor3=Color3.fromRGB(70,70,70)incBtn.TextColor3=Color3.new(1,1,1)incBtn.Font=Enum.Font.SourceSansBold incBtn.TextSize=18 incBtn.Parent=frame local closeBtn=Instance.new("TextButton")closeBtn.Size=UDim2.new(1,-20,0,30)closeBtn.Position=UDim2.new(0,10,0,40+2*(btnSize+gap)+70)closeBtn.Text="关闭飞行"closeBtn.BackgroundColor3=Color3.fromRGB(200,50,50)closeBtn.TextColor3=Color3.new(1,1,1)closeBtn.Font=Enum.Font.SourceSansBold closeBtn.TextSize=14 closeBtn.Parent=frame local function bindButton(btn,flag)btn.MouseButton1Down:Connect(function()if flag=="up"then flyUp=true elseif flag=="down"then flyDown=true elseif flag=="left"then flyLeft=true elseif flag=="right"then flyRight=true end end)btn.MouseButton1Up:Connect(function()if flag=="up"then flyUp=false elseif flag=="down"then flyDown=false elseif flag=="left"then flyLeft=false elseif flag=="right"then flyRight=false end end)btn.MouseLeave:Connect(function()if flag=="up"then flyUp=false elseif flag=="down"then flyDown=false elseif flag=="left"then flyLeft=false elseif flag=="right"then flyRight=false end end)end bindButton(upBtn,"up")bindButton(downBtn,"down")bindButton(leftBtn,"left")bindButton(rightBtn,"right")local function setFlySpeed(v)FlySpeed=math.clamp(v,10,200)speedLabel.Text="速度: "..FlySpeed end decBtn.MouseButton1Click:Connect(function()setFlySpeed(FlySpeed-10)end)incBtn.MouseButton1Click:Connect(function()setFlySpeed(FlySpeed+10)end)closeBtn.MouseButton1Click:Connect(function()StopFly()end)FlyGui=gui return gui end
function StartFly()if Flying then return end local c=LocalPlayer.Character local r=c and c:FindFirstChild("HumanoidRootPart")local h=c and c:FindFirstChildOfClass("Humanoid")if not r or not h then return end Flying=true CreateFlyGui()FlyGui.Enabled=true local gyro=Instance.new("BodyGyro")gyro.MaxTorque=Vector3.new(1,1,1)*400000 gyro.P=10000 gyro.D=100 gyro.CFrame=r.CFrame gyro.Parent=r FlyBodyGyro=gyro local vel=Instance.new("BodyVelocity")vel.MaxForce=Vector3.new(1,1,1)*400000 vel.Velocity=Vector3.zero vel.Parent=r FlyBodyVelocity=vel h.PlatformStand=true end
function StopFly()if not Flying then return end Flying=false if FlyGui then FlyGui.Enabled=false end if FlyBodyGyro then FlyBodyGyro:Destroy()FlyBodyGyro=nil end if FlyBodyVelocity then FlyBodyVelocity:Destroy()FlyBodyVelocity=nil end local c=LocalPlayer.Character local h=c and c:FindFirstChildOfClass("Humanoid")if h then h.PlatformStand=false end flyUp,flyDown,flyLeft,flyRight=false,false,false,false end
RunService.RenderStepped:Connect(function()if not Flying or not FlyBodyVelocity or not FlyBodyGyro then return end local r=LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")if not r then return end local move=Vector3.zero local cam=Camera.CFrame local forward=cam.LookVector local right=cam.RightVector if flyUp then move+=forward end if flyDown then move-=forward end if flyLeft then move-=right end if flyRight then move+=right end FlyBodyVelocity.Velocity=move*FlySpeed FlyBodyGyro.CFrame=CFrame.lookAt(r.Position,r.Position+cam.LookVector)end)
local function ClearESP()for _,hl in pairs(ESP_Highlights)do if hl and hl.Parent then hl:Destroy()end end for _,bb in pairs(ESP_Billboards)do if bb and bb.Parent then bb:Destroy()end end ESP_Highlights={}ESP_Billboards={}end
local function UpdateESP()ClearESP()if not(ESP_Players or ESP_NPCs)then return end local function processModel(m,isPlayer)if m==LocalPlayer.Character then return end local h=m:FindFirstChildOfClass("Humanoid")local hrp=m:FindFirstChild("HumanoidRootPart")local head=m:FindFirstChild("Head")if h and hrp then local hl=Instance.new("Highlight")hl.FillColor=isPlayer and Color3.fromRGB(255,0,0)or Color3.fromRGB(0,255,0)hl.OutlineColor=Color3.new(1,1,1)hl.FillTransparency=0.5 hl.OutlineTransparency=0 hl.Parent=m table.insert(ESP_Highlights,hl)if ESP_ShowName or ESP_ShowDistance or ESP_ShowHealth then local bill=Instance.new("BillboardGui")bill.Size=UDim2.new(0,200,0,60)bill.StudsOffset=Vector3.new(0,2.5,0)bill.AlwaysOnTop=true bill.Parent=head or hrp table.insert(ESP_Billboards,bill)local label=Instance.new("TextLabel")label.Size=UDim2.new(1,0,1,0)label.BackgroundTransparency=1 label.TextColor3=Color3.new(1,1,1)label.TextStrokeTransparency=0 label.Font=Enum.Font.SourceSansBold label.TextSize=14 label.Parent=bill local function update()local parts={}if ESP_ShowName then table.insert(parts,m.Name)end if ESP_ShowDistance and LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("HumanoidRootPart")then local d=(hrp.Position-LocalPlayer.Character.HumanoidRootPart.Position).Magnitude table.insert(parts,string.format("距离: %.1f",d))end if ESP_ShowHealth then table.insert(parts,"血量: "..math.floor(h.Health))end label.Text=table.concat(parts,"\n")end update()RunService.Heartbeat:Connect(function()if bill.Parent then update()end end)end end end if ESP_Players then for _,p in ipairs(Players:GetPlayers())do if p~=LocalPlayer and p.Character then processModel(p.Character,true)end end end if ESP_NPCs then for _,m in ipairs(workspace:GetDescendants())do if m:IsA("Model")and m:FindFirstChildOfClass("Humanoid")then local isPlayer=false for _,p in ipairs(Players:GetPlayers())do if p.Character==m then isPlayer=true break end end if not isPlayer and m~=LocalPlayer.Character then processModel(m,false)end end end end end
Players.PlayerAdded:Connect(function(p)p.CharacterAdded:Connect(function()if ESP_Players then UpdateESP()end end)end)LocalPlayer.CharacterAdded:Connect(function()if ESP_Players or ESP_NPCs then UpdateESP()end end)
local Window=WindUI:CreateWindow({Title="红星中心",Icon="solar:star-bold-duotone",NewElements=true,HideSearchBar=true,Size=UDim2.fromOffset(680,620),OpenButton={Title="打开红星中心",CornerRadius=UDim.new(1,0),StrokeThickness=3,Enabled=true,Draggable=true,OnlyMobile=false,Scale=0.75,Color=ColorSequence.new(Color3.fromHex("#FF4B4B"),Color3.fromHex("#FF9F43"))},Topbar={Height=44,ButtonsType="Mac"}})
local MainTab=Window:Tab({Title="主页",Desc="红星中心公告",Icon="solar:home-2-bold",IconColor=Color3.fromHex("#FF5E5E"),IconShape="Square",Border=true})local NoticeSection=MainTab:Section({Title="📢 公告"})NoticeSection:Section({Title="欢迎使用红星中心 喜欢的话可以加群 1106456119",TextSize=16,TextTransparency=0.2,FontWeight=Enum.FontWeight.Medium})NoticeSection:Space()NoticeSection:Button({Title="点击复制群号",Icon="solar:copy-bold",Color=Color3.fromHex("#FF5E5E"),Justify="Center",Callback=function()setclipboard("1106456119")pcall(function()WindUI:Notify({Title="复制成功",Content="群号 1106456119 已复制到剪贴板",Icon="check-circle",Duration=3})end)end})NoticeSection:Button({Title="复制完整公告",Icon="solar:document-text-bold",Color=Color3.fromHex("#4A90E2"),Justify="Center",Callback=function()setclipboard("欢迎使用红星中心 喜欢的话可以加群 1106456119")pcall(function()WindUI:Notify({Title="复制成功",Content="公告内容已复制",Icon="check-circle",Duration=3})end)end})
local GeneralTab=Window:Tab({Title="通用",Desc="通用功能",Icon="solar:settings-bold",IconColor=Color3.fromHex("#257AF7"),IconShape="Square",Border=true})local GeneralSection=GeneralTab:Section({Title="通用功能"})GeneralSection:Toggle({Title="启用速度修改",Default=false,Callback=function(v)SetSpeedEnabled(v)end})GeneralSection:Slider({Title="移动速度",Min=16,Max=400,Default=16,Callback=function(v)SetSpeedValue(v)end})GeneralSection:Toggle({Title="启用跳跃修改",Default=false,Callback=function(v)SetJumpEnabled(v)end})GeneralSection:Slider({Title="跳跃高度",Min=50,Max=600,Default=50,Callback=function(v)SetJumpValue(v)end})GeneralSection:Toggle({Title="无限跳跃",Default=false,Callback=function(v)InfiniteJumpEnabled=v end})GeneralSection:Button({Title="切换飞行",Icon="solar:rocket-bold",Color=Color3.fromHex("#9B59B6"),Justify="Center",Callback=function()if not Flying then StartFly()else StopFly()end end})
local AimEnabled=false local AimFOV=100 local AimSmoothness=8 local AimVisibleOnly=true local AimGui=Instance.new("ScreenGui")AimGui.Parent=game.CoreGui AimGui.IgnoreGuiInset=true local AimCircle=Instance.new("Frame")AimCircle.Size=UDim2.new(0,AimFOV*2,0,AimFOV*2)AimCircle.AnchorPoint=Vector2.new(0.5,0.5)AimCircle.Position=UDim2.new(0.5,0,0.5,0)AimCircle.BackgroundTransparency=1 AimCircle.BorderSizePixel=0 AimCircle.Visible=false Instance.new("UICorner",AimCircle).CornerRadius=UDim.new(1,0)local AimStroke=Instance.new("UIStroke")AimStroke.Thickness=1.5 AimStroke.Color=Color3.fromRGB(255,0,0)AimStroke.Parent=AimCircle AimCircle.Parent=AimGui local function GetNearestTarget()local best=nil local bestDist=AimFOV local center=Vector2.new(Camera.ViewportSize.X/2,Camera.ViewportSize.Y/2)for _,p in ipairs(Players:GetPlayers())do if p~=LocalPlayer then local c=p.Character if c then local hrp=c:FindFirstChild("HumanoidRootPart")local h=c:FindFirstChildOfClass("Humanoid")if hrp and h and h.Health>0 then local sp,ons=Camera:WorldToScreenPoint(hrp.Position)if ons then local d=(Vector2.new(sp.X,sp.Y)-center).Magnitude if d<=AimFOV then local visible=true if AimVisibleOnly then local ro=Camera.CFrame.Position local rd=(hrp.Position-ro).Unit*500 local rp=RaycastParams.new()rp.FilterType=Enum.RaycastFilterType.Exclude rp.FilterDescendantsInstances={LocalPlayer.Character}local rr=workspace:Raycast(ro,rd,rp)if rr and rr.Instance and not rr.Instance:IsDescendantOf(c)then visible=false end end if visible and d<bestDist then bestDist=d best=hrp end end end end end end end return best end RunService.RenderStepped:Connect(function(dt)if not AimEnabled then AimCircle.Visible=false return end AimCircle.Visible=true AimCircle.Size=UDim2.new(0,AimFOV*2,0,AimFOV*2)local target=GetNearestTarget()if target then local desired=CFrame.lookAt(Camera.CFrame.Position,target.Position)local alpha=math.clamp(1/AimSmoothness,0.01,1)Camera.CFrame=Camera.CFrame:Lerp(desired,alpha*dt*60)end end)
local AimTab=Window:Tab({Title="自瞄",Desc="自瞄功能",Icon="solar:target-bold",IconColor=Color3.fromHex("#EF4F1D"),IconShape="Square",Border=true})local AimSection=AimTab:Section({Title="自瞄设置"})AimSection:Toggle({Title="启用自瞄",Default=false,Callback=function(v)AimEnabled=v if not v then AimCircle.Visible=false end end})AimSection:Slider({Title="自瞄圈大小",Min=50,Max=300,Default=100,Callback=function(v)AimFOV=v end})AimSection:Slider({Title="平滑度",Min=1,Max=20,Default=8,Callback=function(v)AimSmoothness=v end})AimSection:Toggle({Title="出掩体才锁定",Default=true,Callback=function(v)AimVisibleOnly=v end})
local EspTab=Window:Tab({Title="透视",Desc="透视功能",Icon="solar:eye-bold",IconColor=Color3.fromHex("#10C550"),IconShape="Square",Border=true})local EspSection=EspTab:Section({Title="透视设置"})EspSection:Toggle({Title="透视真人",Default=false,Callback=function(v)ESP_Players=v UpdateESP()end})EspSection:Toggle({Title="透视NPC",Default=false,Callback=function(v)ESP_NPCs=v UpdateESP()end})EspSection:Toggle({Title="显示名字",Default=false,Callback=function(v)ESP_ShowName=v UpdateESP()end})EspSection:Toggle({Title="显示距离",Default=false,Callback=function(v)ESP_ShowDistance=v UpdateESP()end})EspSection:Toggle({Title="显示血量",Default=false,Callback=function(v)ESP_ShowHealth=v UpdateESP()end})